declare
  d jsonb := '{"recipes":[{"slug":"butter-chicken","name":"Butter Chicken","description":"Grilled chicken pieces simmered in a smooth, buttery tomato and cream gravy.","category":"Main Course","cuisine":"Pakistani","minutes":50,"servings":4,"taste":{"sweet":4,"salty":5,"sour":3,"spicy":4},"lines":[["Chicken Boneless (Boti)",600,"600 g"],["Yogurt (Dahi)",120,"1/2 cup"],["Tomato",400,"4 medium, pureed"],["Butter (Makhan)",50,"4 tbsp"],["Fresh Cream (Malai)",100,"1/2 cup"],["Ginger Garlic Paste",20,"1 tbsp"],["Kashmiri Chilli Powder",6,"2 tsp"],["Garam Masala",3,"1 tsp"],["Kasuri Methi",2,"1 tsp"],["Salt",7,"1 1/4 tsp"],["White Sugar",5,"1 tsp"]],"steps":["Marinate the chicken with yogurt, half the ginger garlic paste, chilli powder and salt for 30 minutes.","Sear the chicken in a hot pan until charred at the edges; set aside.","Melt the butter, add the rest of the ginger garlic paste and the tomato puree; cook until thick and glossy (10 minutes).","Add the chicken, garam masala, sugar and crushed kasuri methi; simmer for 8 minutes.","Stir in the cream, warm through and serve with naan."]},{"slug":"chicken-white-karahi","name":"White Chicken Karahi","description":"A creamy, peppery karahi made with yogurt and cream instead of tomatoes.","category":"Main Course","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Chicken Leg Piece",750,"750 g"],["Yogurt (Dahi)",200,"3/4 cup"],["Fresh Cream (Malai)",100,"1/2 cup"],["Ginger Garlic Paste",20,"1 tbsp"],["Green Chilli",25,"5, slit"],["Black Pepper",4,"1 tsp, crushed"],["White Pepper",2,"1/2 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Cooking Oil",50,"1/4 cup"],["Salt",8,"1 1/2 tsp"],["Ginger",10,"julienned"]],"steps":["Fry the chicken in the oil with the ginger garlic paste until it turns white.","Add salt, both peppers and cumin; stir for 2 minutes.","Add the whisked yogurt and cook on high heat until the chicken is tender and the oil shows (12 minutes).","Add green chillies and cream, cook for 3 minutes and finish with julienned ginger."]},{"slug":"chicken-malai-boti","name":"Chicken Malai Boti","description":"Tender boneless chicken marinated in cream, cheese and mild spices, then grilled.","category":"Snacks","cuisine":"Pakistani","minutes":45,"servings":4,"taste":{"sweet":1,"salty":5,"sour":2,"spicy":3},"lines":[["Chicken Boneless (Boti)",600,"600 g"],["Fresh Cream (Malai)",80,"1/3 cup"],["Yogurt (Dahi)",60,"1/4 cup"],["Processed Cheese Slice",40,"2 slices"],["Ginger Garlic Paste",15,"1 tbsp"],["White Pepper",3,"1 tsp"],["Green Chilli",10,"2, ground"],["Lemon",15,"juice of 1/2"],["Salt",6,"1 tsp"],["Butter (Makhan)",20,"for basting"]],"steps":["Blend cream, yogurt, cheese, ginger garlic paste, green chilli, white pepper, lemon juice and salt.","Coat the chicken and marinate for at least 1 hour.","Thread onto skewers and grill or bake at 220 °C for 15-18 minutes, basting with butter.","Rest for 2 minutes and serve with mint chutney."]},{"slug":"chicken-kofta-curry","name":"Chicken Kofta Curry","description":"Soft minced-chicken meatballs cooked in a spiced onion-tomato gravy.","category":"Main Course","cuisine":"Pakistani","minutes":55,"servings":4,"taste":{"sweet":1,"salty":6,"sour":3,"spicy":6},"lines":[["Chicken Qeema",500,"500 g"],["Onion",250,"2, 1 grated for koftas"],["Tomato",250,"2 large"],["Gram Flour (Besan)",20,"2 tbsp"],["Ginger Garlic Paste",20,"1 tbsp"],["Green Chilli",10,"2"],["Red Chilli Powder",5,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Garam Masala",3,"1 tsp"],["Yogurt (Dahi)",100,"1/2 cup"],["Cooking Oil",60,"1/4 cup"],["Salt",8,"1 1/2 tsp"],["Fresh Coriander",10,"chopped"]],"steps":["Mix the qeema with grated onion, besan, half the garam masala, green chilli and salt; shape into small balls.","Fry the sliced onion in oil until golden, add ginger garlic paste, tomatoes and spices; bhuno until the oil separates.","Add yogurt and 1 cup water and bring to a simmer.","Slide in the koftas, cover and cook on low heat for 20 minutes without stirring.","Finish with garam masala and coriander."]},{"slug":"chicken-haleem","name":"Chicken Haleem","description":"Slow-cooked lentils, cracked wheat and shredded chicken, beaten into a thick, hearty stew.","category":"Main Course","cuisine":"Pakistani","minutes":150,"servings":6,"taste":{"sweet":1,"salty":6,"sour":3,"spicy":6},"lines":[["Chicken Boneless (Boti)",600,"600 g"],["Cracked Wheat (Dalia)",150,"3/4 cup, soaked"],["Chana Dal",60,"1/3 cup"],["Masoor Dal",40,"1/4 cup"],["Moong Dal",40,"1/4 cup"],["Mash Dal",40,"1/4 cup"],["Onion",300,"3, sliced and fried"],["Ginger Garlic Paste",30,"2 tbsp"],["Red Chilli Powder",8,"2 tsp"],["Turmeric (Haldi)",3,"1 tsp"],["Garam Masala",4,"1 tsp"],["Cooking Oil",100,"1/2 cup"],["Salt",12,"2 tsp"],["Lemon",30,"to serve"],["Fresh Mint (Pudina)",10,"to serve"]],"steps":["Boil the soaked wheat and all dals with turmeric until completely soft (about 1 hour).","Cook the chicken with ginger garlic paste, chilli, salt and half the fried onion until tender; shred it.","Combine the chicken with the lentils and beat (ghotna) over low heat for 30 minutes until stringy and thick.","Add garam masala and adjust salt.","Serve topped with fried onion, mint, ginger and lemon."]},{"slug":"chicken-steam-roast","name":"Chicken Steam Roast","description":"Whole chicken marinated in yogurt and spices, steamed until tender and then pan-roasted.","category":"Main Course","cuisine":"Pakistani","minutes":70,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Whole Chicken",1200,"1 small chicken, skinned, slashed"],["Yogurt (Dahi)",150,"2/3 cup"],["Lemon",30,"juice of 1"],["Ginger Garlic Paste",25,"1 1/2 tbsp"],["Red Chilli Powder",6,"1 1/2 tsp"],["Tikka Masala",15,"1 1/2 tbsp"],["Black Pepper",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",10,"1 3/4 tsp"]],"steps":["Mix yogurt, lemon, ginger garlic paste, chilli, tikka masala, pepper and salt; rub into the chicken and marinate for 2 hours.","Steam the chicken for 30-35 minutes until cooked through.","Heat the oil and roast the chicken on all sides until browned, spooning the juices over it.","Serve with salad and chutney."]},{"slug":"mutton-qorma","name":"Mutton Qorma","description":"Slow-cooked mutton in a rich fried-onion, yogurt and whole-spice gravy.","category":"Main Course","cuisine":"Pakistani","minutes":120,"servings":6,"taste":{"sweet":2,"salty":6,"sour":2,"spicy":5},"lines":[["Mutton",1000,"1 kg"],["Onion",300,"3, sliced and fried golden"],["Yogurt (Dahi)",250,"1 cup"],["Ginger Garlic Paste",30,"2 tbsp"],["Korma Masala",30,"3 tbsp"],["Green Cardamom (Elaichi)",2,"4"],["Cloves (Laung)",1,"4"],["Cinnamon (Dalchini)",2,"1 stick"],["Cooking Oil",120,"1/2 cup"],["Salt",12,"2 tsp"],["Kewra Water",5,"1 tsp"]],"steps":["Heat the oil with the whole spices, add the mutton and ginger garlic paste and brown well.","Add the yogurt blended with the crushed fried onion, korma masala and salt.","Add 2 cups water, cover and cook on low heat for 1 1/2 hours until the meat is very tender.","Cook uncovered until the oil rises, sprinkle kewra and serve with naan."]},{"slug":"mutton-paya","name":"Mutton Paya","description":"Trotters slow-cooked overnight into a sticky, spiced broth, a classic winter breakfast.","category":"Main Course","cuisine":"Pakistani","minutes":300,"servings":6,"taste":{"sweet":0,"salty":6,"sour":2,"spicy":7},"lines":[["Mutton Paya",1500,"6-8 trotters, cleaned"],["Onion",250,"2, sliced"],["Ginger Garlic Paste",40,"2 1/2 tbsp"],["Red Chilli Powder",10,"2 tsp"],["Turmeric (Haldi)",3,"1 tsp"],["Coriander Powder",8,"2 tsp"],["Garam Masala",5,"1 tsp"],["Yogurt (Dahi)",120,"1/2 cup"],["Cooking Oil",120,"1/2 cup"],["Salt",15,"2 1/2 tsp"],["Ginger",15,"julienned"],["Lemon",30,"to serve"]],"steps":["Fry the onions until golden; add ginger garlic paste and the spices with a splash of water.","Add the trotters and yogurt and bhuno for 15 minutes.","Add 3 litres of water and simmer covered for 4-5 hours (or overnight) until the meat falls off the bone.","Adjust salt and garam masala; serve with ginger, green chillies and lemon."]},{"slug":"raan-roast","name":"Mutton Raan Roast","description":"A whole leg of mutton marinated overnight and slow-roasted until it falls apart.","category":"Main Course","cuisine":"Pakistani","minutes":180,"servings":6,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Mutton Leg (Raan)",1800,"1 leg, deeply slashed"],["Yogurt (Dahi)",250,"1 cup"],["Raw Mango (Kairi)",50,"or 2 tbsp papaya paste"],["Ginger Garlic Paste",40,"2 1/2 tbsp"],["Red Chilli Powder",10,"2 tsp"],["Garam Masala",6,"1 1/2 tsp"],["Lemon",40,"juice of 1"],["Cooking Oil",60,"1/4 cup"],["Salt",15,"2 1/2 tsp"]],"steps":["Blend yogurt, raw mango, ginger garlic paste, chilli, garam masala, lemon and salt.","Rub into the leg and marinate overnight in the fridge.","Cook covered with 1 cup water on low heat (or bake at 160 °C) for 2 1/2 hours until tender.","Uncover, baste with oil and roast until browned. Serve with naan and salad."]},{"slug":"beef-seekh-kabab","name":"Beef Seekh Kabab","description":"Spiced beef mince pressed onto skewers and grilled until smoky.","category":"Snacks","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":0,"salty":6,"sour":2,"spicy":6},"lines":[["Beef Qeema",600,"600 g, double minced"],["Onion",100,"1, grated and squeezed"],["Ginger Garlic Paste",15,"1 tbsp"],["Green Chilli",15,"3, finely chopped"],["Fresh Coriander",10,"chopped"],["Red Chilli Flakes (Kuti Lal Mirch)",4,"1 tsp"],["Garam Masala",3,"1 tsp"],["Roasted Chana",20,"2 tbsp, ground"],["Salt",8,"1 1/2 tsp"],["Butter (Makhan)",20,"for basting"]],"steps":["Mix all ingredients except the butter and knead for 5 minutes; rest for 30 minutes.","Wet your hands and press the mixture onto skewers.","Grill over high heat for 10-12 minutes, turning and basting with butter.","Serve with onion rings, lemon and mint chutney."]},{"slug":"bhuna-gosht","name":"Beef Bhuna Gosht","description":"Beef slow-cooked and then stir-fried until the masala darkens and clings to the meat.","category":"Main Course","cuisine":"Pakistani","minutes":90,"servings":4,"taste":{"sweet":0,"salty":6,"sour":3,"spicy":7},"lines":[["Beef Boneless",750,"750 g"],["Onion",250,"2, sliced"],["Tomato",200,"2"],["Ginger Garlic Paste",25,"1 1/2 tbsp"],["Yogurt (Dahi)",100,"1/2 cup"],["Red Chilli Powder",8,"2 tsp"],["Coriander Powder",6,"1 1/2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Garam Masala",4,"1 tsp"],["Cooking Oil",80,"1/3 cup"],["Salt",10,"1 3/4 tsp"],["Green Chilli",15,"3"]],"steps":["Fry the onions until golden; add the beef and ginger garlic paste and sear well.","Add the spices, tomatoes and yogurt; cook for 5 minutes.","Add 2 cups water, cover and cook on low heat for 1 hour until tender.","Uncover and bhuno on high heat, stirring, until the masala is dark and dry. Add green chillies and garam masala."]},{"slug":"mutton-pulao","name":"Mutton Pulao","description":"Fragrant rice cooked in a whole-spice mutton stock (yakhni) with fried onions.","category":"Rice","cuisine":"Pakistani","minutes":120,"servings":6,"taste":{"sweet":1,"salty":6,"sour":1,"spicy":3},"lines":[["Mutton",750,"750 g"],["Basmati Rice",500,"2 1/2 cups, soaked"],["Onion",200,"2, sliced"],["Ginger",20,"1 piece"],["Garlic",20,"1 bulb"],["Coriander Seeds (Sabut Dhania)",8,"1 tbsp"],["Fennel Seeds (Saunf)",5,"1 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Black Cardamom (Bari Elaichi)",2,"2"],["Cloves (Laung)",1,"5"],["Cooking Oil",100,"1/2 cup"],["Salt",15,"2 1/2 tsp"],["Yogurt (Dahi)",100,"1/2 cup"]],"steps":["Tie the ginger, garlic, coriander and fennel seeds in a muslin bag; boil with the mutton in 6 cups water for 1 hour to make yakhni.","Fry the onions golden in oil, add cumin, cardamom and cloves, then the mutton pieces and yogurt.","Add 4 cups of strained yakhni and salt; bring to a boil.","Add the drained rice, cook until the water is absorbed, then steam on low heat for 15 minutes."]},{"slug":"rohu-fish-curry","name":"Rohu Fish Curry","description":"River fish simmered in a tangy tomato and mustard-seed gravy.","category":"Main Course","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":0,"salty":6,"sour":5,"spicy":6},"lines":[["Rohu Fish",750,"750 g, steaks"],["Tomato",300,"3"],["Onion",150,"1 large"],["Ginger Garlic Paste",15,"1 tbsp"],["Mustard Seeds (Sarson)",3,"1 tsp"],["Turmeric (Haldi)",3,"1 tsp"],["Red Chilli Powder",6,"1 1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Tamarind (Imli)",15,"1 tbsp pulp"],["Mustard Oil",50,"1/4 cup"],["Salt",8,"1 1/2 tsp"],["Fresh Coriander",10,"chopped"]],"steps":["Rub the fish with turmeric and salt and lightly fry; set aside.","In the same oil splutter the mustard seeds, then fry the onion and ginger garlic paste.","Add tomatoes and spices; cook until soft, then add 1 1/2 cups water and the tamarind.","Slide in the fish and simmer for 8 minutes without stirring. Garnish with coriander."]},{"slug":"fish-tikka","name":"Surmai Fish Tikka","description":"King fish cubes marinated in yogurt, lemon and carom seeds, then grilled.","category":"Snacks","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":0,"salty":6,"sour":5,"spicy":6},"lines":[["Surmai Fish (King Fish)",600,"600 g, cubed"],["Yogurt (Dahi)",80,"1/3 cup"],["Lemon",30,"juice of 1"],["Carom Seeds (Ajwain)",2,"1/2 tsp"],["Ginger Garlic Paste",15,"1 tbsp"],["Kashmiri Chilli Powder",5,"1 1/2 tsp"],["Gram Flour (Besan)",15,"1 1/2 tbsp"],["Chaat Masala",3,"1 tsp"],["Salt",6,"1 tsp"],["Cooking Oil",20,"for basting"]],"steps":["Marinate the fish with lemon and salt for 10 minutes.","Mix in yogurt, besan, carom seeds, ginger garlic paste and chilli; rest for 20 minutes.","Grill on skewers for 8-10 minutes, basting with oil.","Sprinkle chaat masala and serve with lemon wedges."]},{"slug":"anda-curry","name":"Anda Curry","description":"Boiled eggs in a home-style onion-tomato masala.","category":"Main Course","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Eggs",300,"6, boiled and peeled"],["Onion",200,"2"],["Tomato",250,"2 large"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",5,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Cooking Oil",50,"1/4 cup"],["Salt",7,"1 1/4 tsp"],["Fresh Coriander",10,"chopped"],["Green Chilli",10,"2"]],"steps":["Lightly fry the boiled eggs with a pinch of turmeric; set aside.","Fry the onions golden, add ginger garlic paste, tomatoes and spices; bhuno until the oil separates.","Add 1 cup water, then the eggs; simmer for 8 minutes.","Finish with garam masala, green chillies and coriander."]},{"slug":"palak-paneer","name":"Palak Paneer","description":"Cubes of paneer in a smooth, garlicky spinach gravy.","category":"Vegetables","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":2,"spicy":4},"lines":[["Spinach",500,"500 g"],["Paneer",250,"250 g, cubed"],["Onion",120,"1"],["Tomato",100,"1"],["Garlic",15,"5 cloves"],["Ginger",10,"1 inch"],["Green Chilli",10,"2"],["Cumin (Zeera)",3,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Fresh Cream (Malai)",40,"3 tbsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Blanch the spinach with the green chillies for 2 minutes, cool and blend smooth.","Heat oil, crackle the cumin, then fry onion, garlic and ginger until golden.","Add the tomato and cook until soft; add the spinach puree and salt and simmer for 5 minutes.","Add the paneer and garam masala, simmer 3 minutes and finish with cream."]},{"slug":"matar-paneer","name":"Matar Paneer","description":"Peas and paneer in a lightly spiced tomato gravy.","category":"Vegetables","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":2,"salty":5,"sour":3,"spicy":5},"lines":[["Paneer",250,"250 g"],["Green Peas",250,"1 1/2 cups"],["Tomato",300,"3"],["Onion",120,"1"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",4,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Fry the onion until soft, add ginger garlic paste and spices.","Add pureed tomatoes and cook until the oil separates.","Add peas and 1 cup water; cook for 8 minutes.","Add paneer cubes and garam masala and simmer for 4 minutes."]},{"slug":"mix-sabzi","name":"Mix Sabzi","description":"Seasonal vegetables cooked together with cumin and a little tomato.","category":"Vegetables","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":2,"salty":5,"sour":2,"spicy":4},"lines":[["Potato",200,"2"],["Carrot",150,"2"],["Green Peas",150,"1 cup"],["Cauliflower",200,"1 small"],["Green Beans (Fali)",100,"a handful"],["Tomato",150,"1 large"],["Onion",100,"1"],["Cumin (Zeera)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"]],"steps":["Crackle cumin in oil and fry the onion until soft.","Add tomato and spices and cook for 3 minutes.","Add all vegetables and salt, cover and cook on low heat for 15-20 minutes until tender.","Uncover and stir-fry for 2 minutes."]},{"slug":"aloo-matar","name":"Aloo Matar","description":"Potatoes and peas in a simple home-style tomato curry.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":2,"salty":5,"sour":3,"spicy":5},"lines":[["Potato",400,"3 medium, cubed"],["Green Peas",250,"1 1/2 cups"],["Tomato",250,"2"],["Onion",100,"1"],["Ginger Garlic Paste",10,"2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",5,"1 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"],["Fresh Coriander",10,"chopped"]],"steps":["Crackle cumin in oil, add onion and ginger garlic paste and fry until golden.","Add tomatoes and spices; cook until soft.","Add potatoes, peas and 1 1/2 cups water; cover and cook for 15 minutes.","Garnish with coriander."]},{"slug":"aloo-methi","name":"Aloo Methi","description":"Potatoes stir-fried with fresh fenugreek leaves and garlic.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":1,"salty":5,"sour":1,"spicy":4},"lines":[["Potato",500,"4 medium"],["Fenugreek Leaves (Methi)",150,"2 bunches, chopped"],["Garlic",15,"5 cloves"],["Cumin (Zeera)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Flakes (Kuti Lal Mirch)",3,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Crackle cumin and garlic in oil.","Add potatoes, turmeric, chilli and salt; cover and cook for 10 minutes.","Add the methi and stir-fry on medium heat until the potatoes are tender and the leaves wilt (8 minutes)."]},{"slug":"karela-qeema","name":"Karela Qeema","description":"Bitter gourd cooked with spiced beef mince; the bitterness balances the rich qeema.","category":"Main Course","cuisine":"Pakistani","minutes":55,"servings":4,"taste":{"sweet":1,"salty":6,"sour":3,"spicy":6},"lines":[["Bitter Gourd (Karela)",400,"4, scraped and sliced"],["Beef Qeema",400,"400 g"],["Onion",200,"2"],["Tomato",200,"2"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",6,"1 1/2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Cooking Oil",70,"1/3 cup"],["Salt",10,"1 3/4 tsp"]],"steps":["Rub the karela with salt for 30 minutes, rinse and fry until browned; set aside.","Fry onions, add ginger garlic paste and the qeema and cook until browned.","Add tomatoes and spices and bhuno until the oil separates.","Add the karela, cover and cook on low heat for 10 minutes."]},{"slug":"tinda-masala","name":"Tinda Masala","description":"Tender apple gourds in a light tomato and onion masala.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Apple Gourd (Tinda)",500,"6, peeled and quartered"],["Tomato",200,"2"],["Onion",100,"1"],["Ginger Garlic Paste",10,"2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Coriander Powder",5,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"],["Fresh Coriander",8,"chopped"]],"steps":["Fry the onion and ginger garlic paste until golden.","Add tomatoes and spices and cook until soft.","Add the tinda and 1/2 cup water; cover and cook for 15 minutes until tender.","Garnish with coriander."]},{"slug":"kaddu-ki-sabzi","name":"Khatta Meetha Kaddu","description":"Sweet-and-sour pumpkin with fenugreek seeds, jaggery and tamarind.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":6,"salty":4,"sour":5,"spicy":3},"lines":[["Pumpkin (Kaddu)",600,"600 g, cubed"],["Jaggery (Gur)",25,"2 tbsp"],["Tamarind (Imli)",15,"1 tbsp pulp"],["Fenugreek (Methi Dana)",2,"1/2 tsp"],["Fennel Seeds (Saunf)",3,"1 tsp"],["Red Chilli Powder",3,"3/4 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Mustard Oil",30,"2 tbsp"],["Salt",5,"1 tsp"]],"steps":["Heat mustard oil and crackle the fenugreek and fennel seeds.","Add pumpkin, turmeric, chilli and salt; cover and cook for 12 minutes, mashing lightly.","Stir in jaggery and tamarind and cook for 3 more minutes."]},{"slug":"band-gobhi","name":"Band Gobhi Matar","description":"Shredded cabbage and peas stir-fried with cumin and green chillies.","category":"Vegetables","cuisine":"Pakistani","minutes":25,"servings":4,"taste":{"sweet":2,"salty":5,"sour":2,"spicy":4},"lines":[["Cabbage",500,"1 small, shredded"],["Green Peas",150,"1 cup"],["Tomato",100,"1"],["Green Chilli",10,"2"],["Cumin (Zeera)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",3,"3/4 tsp"],["Cooking Oil",30,"2 tbsp"],["Salt",6,"1 tsp"]],"steps":["Crackle cumin in oil, add the tomato and spices.","Add the cabbage, peas, green chillies and salt.","Cover and cook on low heat for 12 minutes, then stir-fry until dry."]},{"slug":"lauki-chana-dal","name":"Lauki Chana Dal","description":"Bottle gourd and split chickpeas cooked together, finished with a garlic tadka.","category":"Lentils","cuisine":"Pakistani","minutes":50,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Bottle Gourd (Lauki)",400,"1 medium, cubed"],["Chana Dal",150,"3/4 cup, soaked"],["Tomato",150,"1 large"],["Onion",100,"1"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Garlic",10,"4 cloves"],["Cumin (Zeera)",3,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"]],"steps":["Boil the chana dal with turmeric until half cooked (20 minutes).","Fry the onion and tomato with chilli and salt; add the dal and lauki.","Cover and cook for 15 minutes until both are tender.","Make a tadka of cumin and sliced garlic in hot oil and pour over."]},{"slug":"arvi-masala","name":"Arvi Masala","description":"Colocasia cooked dry with carom seeds and dried mango powder.","category":"Vegetables","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":1,"salty":5,"sour":4,"spicy":5},"lines":[["Colocasia (Arvi)",500,"500 g, boiled and peeled"],["Onion",100,"1"],["Carom Seeds (Ajwain)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Coriander Powder",5,"1 tsp"],["Dried Mango Powder (Amchur)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Slice the boiled arvi.","Crackle ajwain in oil, fry the onion until soft and add the spices.","Add the arvi and stir-fry until crisp at the edges (10 minutes); finish with amchur."]},{"slug":"moong-daal","name":"Moong Daal","description":"Yellow moong lentils simmered soft and finished with a cumin and garlic tadka.","category":"Lentils","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":2,"spicy":4},"lines":[["Moong Dal",200,"1 cup, washed"],["Turmeric (Haldi)",2,"1/2 tsp"],["Tomato",100,"1"],["Green Chilli",10,"2"],["Garlic",10,"4 cloves"],["Cumin (Zeera)",3,"1 tsp"],["Whole Red Chilli (Sabut Lal Mirch)",2,"2"],["Desi Ghee",25,"2 tbsp"],["Salt",6,"1 tsp"],["Fresh Coriander",8,"chopped"]],"steps":["Boil the dal with turmeric, tomato, green chilli and salt in 4 cups water until soft (25 minutes).","Heat ghee, fry cumin, garlic and whole red chillies until golden.","Pour the tadka over the dal and garnish with coriander."]},{"slug":"chana-daal","name":"Chana Daal Tadka","description":"Split chickpeas cooked until creamy, with an onion and tomato tadka.","category":"Lentils","cuisine":"Pakistani","minutes":50,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":5},"lines":[["Chana Dal",200,"1 cup, soaked 1 hour"],["Onion",120,"1"],["Tomato",150,"1 large"],["Ginger Garlic Paste",10,"2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"]],"steps":["Boil the chana dal with turmeric and salt until soft (35 minutes).","Fry cumin and onion, add ginger garlic paste, tomato and chilli; cook until thick.","Mix the masala into the dal, simmer for 5 minutes and add garam masala."]},{"slug":"lobia-masala","name":"Lobia Masala","description":"Black-eyed beans in a thick, tangy onion-tomato masala.","category":"Lentils","cuisine":"Pakistani","minutes":60,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":5},"lines":[["Black-eyed Beans (Lobia)",250,"1 1/4 cups, soaked overnight"],["Onion",150,"1 large"],["Tomato",200,"2"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",5,"1 tsp"],["Coriander Powder",5,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Dried Mango Powder (Amchur)",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",8,"1 1/2 tsp"]],"steps":["Pressure-cook or boil the lobia until tender.","Fry the onion, add ginger garlic paste, tomatoes and spices; cook until the oil separates.","Add the lobia with some cooking water and simmer for 10 minutes; finish with amchur."]},{"slug":"kala-chana","name":"Kala Chana Masala","description":"Black chickpeas cooked in a dark, spiced gravy.","category":"Lentils","cuisine":"Pakistani","minutes":70,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Black Chickpeas (Kala Chana)",250,"1 1/4 cups, soaked overnight"],["Onion",150,"1 large"],["Tomato",200,"2"],["Ginger Garlic Paste",15,"1 tbsp"],["Chana Masala",15,"1 1/2 tbsp"],["Pomegranate Seeds Dried (Anardana)",5,"1 tsp, ground"],["Cooking Oil",40,"3 tbsp"],["Salt",8,"1 1/2 tsp"],["Fresh Coriander",8,"chopped"]],"steps":["Boil the chickpeas until soft.","Fry the onion dark golden, add ginger garlic paste, tomatoes and chana masala.","Add the chickpeas with 1 cup cooking water and simmer for 15 minutes.","Stir in anardana and coriander."]},{"slug":"matar-pulao","name":"Matar Pulao","description":"Basmati rice cooked with green peas, cumin and whole spices.","category":"Rice","cuisine":"Pakistani","minutes":45,"servings":4,"taste":{"sweet":1,"salty":5,"sour":1,"spicy":2},"lines":[["Basmati Rice",400,"2 cups, soaked"],["Green Peas",200,"1 1/2 cups"],["Onion",120,"1, sliced"],["Cumin (Zeera)",3,"1 tsp"],["Bay Leaf (Tez Patta)",1,"2"],["Cloves (Laung)",1,"4"],["Black Cardamom (Bari Elaichi)",2,"1"],["Cooking Oil",50,"1/4 cup"],["Salt",10,"1 3/4 tsp"]],"steps":["Fry the onion golden with the whole spices and cumin.","Add the peas and stir for 2 minutes.","Add 3 1/2 cups water and salt and bring to a boil; add the rice.","Cook until the water is absorbed, then steam covered for 12 minutes."]},{"slug":"khichdi","name":"Moong Dal Khichdi","description":"Soft, comforting rice and moong lentils with ghee and cumin.","category":"Rice","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":1,"spicy":2},"lines":[["Basmati Rice",200,"1 cup"],["Moong Dal",100,"1/2 cup"],["Turmeric (Haldi)",2,"1/2 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Desi Ghee",25,"2 tbsp"],["Onion",80,"1 small"],["Salt",7,"1 1/4 tsp"],["Yogurt (Dahi)",150,"to serve"]],"steps":["Wash rice and dal together.","Heat ghee, crackle cumin and fry the onion until soft.","Add rice, dal, turmeric, salt and 5 cups water; cook covered on low heat for 25 minutes until soft.","Serve with yogurt."]},{"slug":"prawn-biryani","name":"Prawn Biryani","description":"Spiced prawns layered with saffron rice and fried onions.","category":"Rice","cuisine":"Pakistani","minutes":60,"servings":5,"taste":{"sweet":1,"salty":6,"sour":5,"spicy":7},"lines":[["Prawns",500,"500 g, cleaned"],["Basmati Rice",400,"2 cups, soaked"],["Onion",200,"2, sliced"],["Tomato",200,"2"],["Yogurt (Dahi)",150,"2/3 cup"],["Biryani Masala",25,"2 1/2 tbsp"],["Ginger Garlic Paste",15,"1 tbsp"],["Green Chilli",15,"3"],["Fresh Mint (Pudina)",10,"a handful"],["Lemon",30,"1"],["Saffron (Zafran)",0.2,"a pinch"],["Cooking Oil",80,"1/3 cup"],["Salt",15,"2 1/2 tsp"]],"steps":["Fry the onions golden; keep half for layering.","Cook ginger garlic paste, tomatoes, yogurt and biryani masala until thick; add the prawns for 4 minutes only.","Boil the rice in salted water until 80% cooked and drain.","Layer rice and prawn masala with mint, chillies, lemon, fried onion and saffron milk.","Steam (dum) on low heat for 15 minutes."]},{"slug":"dahi-bhalla","name":"Dahi Bhalla","description":"Soft lentil dumplings soaked and served in sweet yogurt with chutneys and chaat masala.","category":"Snacks","cuisine":"Pakistani","minutes":60,"servings":6,"taste":{"sweet":6,"salty":5,"sour":5,"spicy":3},"lines":[["Mash Dal",200,"1 cup, soaked overnight"],["Yogurt (Dahi)",500,"2 cups, whisked"],["White Sugar",25,"2 tbsp"],["Tamarind Chutney",60,"1/4 cup"],["Mint Chutney",40,"3 tbsp"],["Chaat Masala",5,"1 1/2 tsp"],["Cumin (Zeera)",3,"1 tsp, roasted and ground"],["Red Chilli Powder",2,"1/2 tsp"],["Cooking Oil",40,"for frying (about 3 tbsp absorbed)"],["Salt",5,"1 tsp"]],"steps":["Grind the soaked dal to a fluffy batter with a little water and salt; beat for 5 minutes.","Drop spoonfuls into hot oil and fry golden; soak the bhallas in warm water for 15 minutes and squeeze gently.","Whisk the yogurt with sugar and a pinch of salt.","Arrange the bhallas, pour over the yogurt and top with chutneys, chaat masala, cumin and chilli."]},{"slug":"chana-chaat","name":"Chana Chaat","description":"Chickpeas tossed with onion, tomato, cucumber, chutney and chaat masala.","category":"Snacks","cuisine":"Pakistani","minutes":15,"servings":4,"taste":{"sweet":3,"salty":5,"sour":7,"spicy":4},"lines":[["Kabuli Chickpeas (Chana)",400,"2 cups, boiled"],["Onion",80,"1 small, chopped"],["Tomato",100,"1, chopped"],["Cucumber",100,"1, diced"],["Green Chilli",5,"1, chopped"],["Tamarind Chutney",40,"3 tbsp"],["Lemon",15,"juice of 1/2"],["Chaat Masala",5,"1 1/2 tsp"],["Fresh Coriander",8,"chopped"],["Salt",3,"1/2 tsp"]],"steps":["Mix the chickpeas with the vegetables.","Add chutney, lemon, chaat masala and salt and toss well.","Garnish with coriander and serve straight away."]},{"slug":"aloo-tikki","name":"Aloo Tikki","description":"Crisp pan-fried potato patties with herbs and spices.","category":"Snacks","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Potato",500,"4, boiled and mashed"],["Corn Flour",20,"2 tbsp"],["Green Chilli",10,"2, chopped"],["Fresh Coriander",10,"chopped"],["Cumin (Zeera)",2,"1/2 tsp, roasted"],["Chaat Masala",3,"1 tsp"],["Red Chilli Flakes (Kuti Lal Mirch)",2,"1/2 tsp"],["Cooking Oil",60,"for shallow frying"],["Salt",5,"1 tsp"]],"steps":["Mix the mashed potato with corn flour, herbs and spices.","Shape into flat patties.","Shallow-fry on medium heat until golden and crisp on both sides.","Serve with tamarind and mint chutney."]},{"slug":"chicken-paratha-roll","name":"Chicken Paratha Roll","description":"Spicy chicken tikka strips wrapped in a crisp paratha with garlic sauce and onions.","category":"Snacks","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":2,"salty":6,"sour":4,"spicy":6},"lines":[["Chicken Boneless (Boti)",400,"400 g, strips"],["Wheat Flour (Atta)",300,"2 cups, for 4 parathas"],["Yogurt (Dahi)",60,"1/4 cup"],["Tikka Masala",15,"1 1/2 tbsp"],["Garlic Sauce",60,"1/4 cup"],["Onion",100,"1, sliced"],["Mint Chutney",30,"2 tbsp"],["Desi Ghee",40,"for parathas"],["Cooking Oil",20,"1 1/2 tbsp"],["Salt",5,"1 tsp"]],"steps":["Marinate the chicken in yogurt and tikka masala for 30 minutes; stir-fry on high heat until charred.","Knead the atta with water and salt; roll and cook four parathas with ghee.","Spread garlic sauce and mint chutney on each paratha, add chicken and onion.","Roll tightly, wrap the end in paper and serve."]},{"slug":"suji-halwa","name":"Suji Halwa","description":"Semolina roasted in ghee and cooked with sugar syrup, cardamom and nuts.","category":"Desserts","cuisine":"Pakistani","minutes":25,"servings":4,"taste":{"sweet":9,"salty":1,"sour":0,"spicy":0},"lines":[["Semolina (Suji)",150,"3/4 cup"],["Desi Ghee",80,"1/3 cup"],["White Sugar",150,"3/4 cup"],["Green Cardamom (Elaichi)",2,"4, crushed"],["Almonds (Badam)",20,"sliced"],["Raisins (Kishmish)",15,"a handful"]],"steps":["Make a syrup with the sugar, cardamom and 2 cups water.","Roast the suji in ghee on low heat until golden and fragrant (10 minutes).","Carefully pour in the hot syrup, stirring, and cook until it leaves the sides.","Garnish with almonds and raisins."]},{"slug":"zarda","name":"Zarda","description":"Sweet saffron rice with nuts and raisins, served at celebrations.","category":"Desserts","cuisine":"Pakistani","minutes":45,"servings":6,"taste":{"sweet":9,"salty":1,"sour":0,"spicy":0},"lines":[["Basmati Rice",300,"1 1/2 cups, soaked"],["White Sugar",250,"1 1/4 cups"],["Desi Ghee",60,"1/4 cup"],["Green Cardamom (Elaichi)",2,"4"],["Cloves (Laung)",1,"4"],["Saffron (Zafran)",0.3,"a pinch, in milk"],["Almonds (Badam)",25,"sliced"],["Raisins (Kishmish)",25,"a handful"],["Khoya (Mawa)",50,"crumbled, optional"]],"steps":["Boil the rice until 80% cooked and drain.","Heat ghee with cardamom and cloves, add the sugar and 1/2 cup water and stir until it melts.","Fold in the rice, saffron, nuts and raisins.","Cover and steam on the lowest heat for 15 minutes; top with khoya."]},{"slug":"firni","name":"Firni","description":"Chilled ground-rice pudding scented with cardamom and kewra, set in clay bowls.","category":"Desserts","cuisine":"Pakistani","minutes":40,"servings":6,"taste":{"sweet":8,"salty":1,"sour":0,"spicy":0},"lines":[["Milk",1000,"1 litre"],["Rice Flour",60,"1/3 cup"],["White Sugar",120,"2/3 cup"],["Green Cardamom (Elaichi)",2,"4, ground"],["Kewra Water",5,"1 tsp"],["Pistachios (Pista)",15,"chopped"]],"steps":["Mix the rice flour with 1/2 cup cold milk.","Bring the rest of the milk to a boil, stir in the rice flour paste and cook on low heat, stirring, for 15 minutes.","Add sugar and cardamom and cook until thick.","Add kewra, pour into bowls, chill and top with pistachios."]},{"slug":"shahi-tukray","name":"Shahi Tukray","description":"Fried bread soaked in syrup and topped with thick, sweet rabri.","category":"Desserts","cuisine":"Pakistani","minutes":45,"servings":6,"taste":{"sweet":9,"salty":1,"sour":0,"spicy":0},"lines":[["Bread",200,"6 slices, crusts removed"],["Desi Ghee",60,"for frying"],["White Sugar",150,"3/4 cup"],["Milk",750,"3 cups"],["Condensed Milk",100,"1/3 cup"],["Green Cardamom (Elaichi)",2,"4"],["Saffron (Zafran)",0.2,"a pinch"],["Pistachios (Pista)",15,"sliced"],["Almonds (Badam)",15,"sliced"]],"steps":["Cut the bread into triangles and fry golden in ghee.","Make a syrup with 1/2 cup sugar and 1/2 cup water; dip the fried bread briefly.","Reduce the milk with the rest of the sugar, condensed milk, cardamom and saffron to a thick rabri (25 minutes).","Pour the rabri over the bread and garnish with nuts."]},{"slug":"gulab-jamun","name":"Gulab Jamun","description":"Soft milk-powder dumplings fried golden and soaked in cardamom syrup.","category":"Desserts","cuisine":"Pakistani","minutes":50,"servings":6,"taste":{"sweet":10,"salty":1,"sour":0,"spicy":0},"lines":[["Milk Powder",150,"1 1/4 cups"],["Refined Flour (Maida)",40,"1/3 cup"],["Baking Powder",3,"1/2 tsp"],["Desi Ghee",20,"1 1/2 tbsp"],["